package sensorhub_test

import (
	"context"
	"errors"
	"fmt"
	"math/rand"
	"testing"

	"example.com/sensorhubmod/sensorhub"
)

func TestCorrectResultsAndErrors(t *testing.T) {
	rng := rand.New(rand.NewSource(500))
	for round := 0; round < 60; round++ {
		n := rng.Intn(14)
		items := makeItems(n + 3)
		ids := make([]string, n)
		wantErr := ""
		for i := range ids {
			if rng.Intn(5) == 0 && (wantErr == "" || true) {
				ids[i] = fmt.Sprintf("ghost%d", i)
				if wantErr == "" {
					wantErr = ids[i]
				}
			} else {
				ids[i] = fmt.Sprintf("id%d", rng.Intn(n+3))
			}
		}
		got, err := sensorhub.FetchReadings(context.Background(), newSlow(items, 0), ids)
		if wantErr != "" {
			var me *missingErr
			if err == nil || !errors.As(err, &me) || me.id != wantErr {
				t.Fatalf("ids %v: error = %v, want missing %s", ids, err, wantErr)
			}
			if got != nil {
				t.Fatalf("ids %v: a failed call must return a nil slice, got %v", ids, got)
			}
			continue
		}
		if err != nil {
			t.Fatalf("ids %v: unexpected error %v", ids, err)
		}
		if len(got) != len(ids) {
			t.Fatalf("ids %v: got %d items", ids, len(got))
		}
		for i, id := range ids {
			if got[i] != items[id] {
				t.Fatalf("ids %v: item %d = %v, want %v", ids, i, got[i], items[id])
			}
		}
	}
}

func TestCorrectEmpty(t *testing.T) {
	got, err := sensorhub.FetchReadings(context.Background(), newSlow(makeItems(2), 0), nil)
	if err != nil || len(got) != 0 {
		t.Fatalf("empty input: %v, %v", got, err)
	}
}

