package sensorhub_test

import (
	"context"
	"fmt"
	"sync"
	"time"

	"example.com/sensorhubmod/sensorhub"
)

// missingErr is what the fake returns for unknown or failing ids.
type missingErr struct{ id string }

func (e *missingErr) Error() string { return "missing " + e.id }

// slowBackend records how many requests were made and how many overlapped. The first calls wait for a rendezvous: until `barrier`
// requests are in flight at the same time (then everybody is released) or, as a safety net, for three seconds.
type slowBackend struct {
	items   map[string]sensorhub.Item
	failing map[string]bool
	barrier int

	mu          sync.Mutex
	started     int
	inflight    int
	maxInflight int
	tripped     chan struct{}
	once        sync.Once
	open        bool
}

func newSlow(items map[string]sensorhub.Item, barrier int) *slowBackend {
	return &slowBackend{items: items, failing: map[string]bool{}, barrier: barrier, tripped: make(chan struct{})}
}

func (b *slowBackend) Get(ctx context.Context, id string) (sensorhub.Item, error) {
	b.mu.Lock()
	b.started++
	if b.failing[id] {
		b.mu.Unlock()
		return sensorhub.Item{}, &missingErr{id}
	}
	b.inflight++
	if b.inflight > b.maxInflight {
		b.maxInflight = b.inflight
	}
	if b.barrier > 0 && b.inflight >= b.barrier {
		b.once.Do(func() { close(b.tripped) })
	}
	waiting := b.barrier > 0 && !b.open
	b.mu.Unlock()
	defer func() {
		b.mu.Lock()
		b.inflight--
		b.mu.Unlock()
	}()
	if waiting {
		select {
		case <-b.tripped:
		case <-ctx.Done():
			return sensorhub.Item{}, ctx.Err()
		case <-time.After(3 * time.Second):
			b.mu.Lock()
			b.open = true
			b.mu.Unlock()
		}
	}
	if err := ctx.Err(); err != nil {
		return sensorhub.Item{}, err
	}
	item, ok := b.items[id]
	if !ok {
		return sensorhub.Item{}, &missingErr{id}
	}
	return item, nil
}

func makeItems(n int) map[string]sensorhub.Item {
	items := map[string]sensorhub.Item{}
	for i := 0; i < n; i++ {
		id := fmt.Sprintf("id%d", i)
		items[id] = sensorhub.Item{ID: id, Value: i * 7}
	}
	return items
}

