package sensorhub

import (
	"context"
	"sync"
)

// FetchReadings loads the items for ids.
func FetchReadings(ctx context.Context, b Backend, ids []string) ([]Item, error) {
	out := make([]Item, len(ids))
	errs := make([]error, len(ids))
	var wg sync.WaitGroup
	for i, id := range ids {
		wg.Add(1)
		go func(i int, id string) {
			defer wg.Done()
			out[i], errs[i] = b.Get(ctx, id)
		}(i, id)
	}
	wg.Wait()
	for _, err := range errs {
		if err != nil {
			return nil, err
		}
	}
	return out, nil
}

