package sensorhub

import "context"

// FetchReadings loads the items for ids.
func FetchReadings(ctx context.Context, b Backend, ids []string) ([]Item, error) {
	out := make([]Item, 0, len(ids))
	for _, id := range ids {
		item, err := b.Get(ctx, id)
		if err != nil {
			return nil, err
		}
		out = append(out, item)
	}
	return out, nil
}

