package profiles_test

import (
	"context"
	"errors"
	"fmt"
	"testing"

	"example.com/profilesmod/profiles"
)

var _ = errors.As
var _ = fmt.Sprintf

func sequence(n int) []string {
	ids := make([]string, n)
	for i := range ids {
		ids[i] = fmt.Sprintf("id%d", i)
	}
	return ids
}

func checkItems(t *testing.T, items map[string]profiles.Item, ids []string, got []profiles.Item, err error) {
	t.Helper()
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(got) != len(ids) {
		t.Fatalf("got %d items for %d ids", len(got), len(ids))
	}
	for i, id := range ids {
		if got[i] != items[id] {
			t.Fatalf("item %d = %v, want %v", i, got[i], items[id])
		}
	}
}

func TestPerfBoundedOnSuccess(t *testing.T) {
	items := makeItems(40)
	ids := sequence(30)
	b := newSlow(items, 3)
	got, err := profiles.LoadProfiles(context.Background(), b, ids)
	checkItems(t, items, ids, got, err)
	if b.maxInflight > 4 || b.maxInflight < 3 {
		t.Fatalf("PERF: %d requests in flight at once (allowed: 3 or 4 with this much work)", b.maxInflight)
	}
}

func TestPerfStopsAfterTheFirstError(t *testing.T) {
	items := makeItems(60)
	ids := sequence(40)
	b := newSlow(items, 100)
	b.failing["id3"] = true
	got, err := profiles.LoadProfiles(context.Background(), b, ids)
	var me *missingErr
	if err == nil || !errors.As(err, &me) || me.id != "id3" {
		t.Fatalf("error = %v, want the error of id3 (not a context error)", err)
	}
	if got != nil {
		t.Fatalf("a failed call must return a nil slice")
	}
	if b.maxInflight > 4 {
		t.Fatalf("PERF: %d requests were in flight at once (the backend allows 4)", b.maxInflight)
	}
	if b.started > 8 {
		t.Fatalf("PERF: %d requests were started although the fourth one failed at once: new requests must stop after the first error", b.started)
	}
}

solution.profiles/load.go:
package profiles

import (
	"context"
	"sync"
)

// LoadProfiles loads the items for ids.
func LoadProfiles(ctx context.Context, b Backend, ids []string) ([]Item, error) {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	out := make([]Item, len(ids))
	jobs := make(chan int)
	var once sync.Once
	var first error
	var wg sync.WaitGroup
	for w := 0; w < 4 && w < len(ids); w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				if ctx.Err() != nil {
					continue
				}
				item, err := b.Get(ctx, ids[i])
				if err != nil {
					once.Do(func() {
						first = err
						cancel()
					})
					continue
				}
				out[i] = item
			}
		}()
	}
	for i := range ids {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	if first != nil {
		return nil, first
	}
	return out, nil
}

