package authordir

import (
	"context"
	"sync"
)

// ResolveAuthors loads the items for ids.
func ResolveAuthors(ctx context.Context, b Backend, ids []string) ([]Item, error) {
	ctx, cancel := context.WithCancel(ctx)
	defer cancel()
	out := make([]Item, len(ids))
	jobs := make(chan int)
	var once sync.Once
	var first error
	var wg sync.WaitGroup
	for w := 0; w < 4 && w < len(ids); w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				if ctx.Err() != nil {
					continue
				}
				item, err := b.Get(ctx, ids[i])
				if err != nil {
					once.Do(func() {
						first = err
						cancel()
					})
					continue
				}
				out[i] = item
			}
		}()
	}
	for i := range ids {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	if first != nil {
		return nil, first
	}
	return out, nil
}

