package profiles

import (
	"context"
	"sync"
)

// LoadProfiles loads the items for ids.
func LoadProfiles(ctx context.Context, b Backend, ids []string) ([]Item, error) {
	index := map[string]int{}
	var distinct []string
	for _, id := range ids {
		if _, ok := index[id]; !ok {
			index[id] = len(distinct)
			distinct = append(distinct, id)
		}
	}
	items := make([]Item, len(distinct))
	errs := make([]error, len(distinct))
	var wg sync.WaitGroup
	for i, id := range distinct {
		wg.Add(1)
		go func(i int, id string) {
			defer wg.Done()
			items[i], errs[i] = b.Get(ctx, id)
		}(i, id)
	}
	wg.Wait()
	out := make([]Item, len(ids))
	for k, id := range ids {
		j := index[id]
		if errs[j] != nil {
			return nil, errs[j]
		}
		out[k] = items[j]
	}
	return out, nil
}

