	return &slowBackend{items: items, failing: map[string]bool{}, barrier: barrier, tripped: make(chan struct{})}
}

func (b *slowBackend) Get(ctx context.Context, id string) (geoenrich.Item, error) {
	b.mu.Lock()
	b.started++
	if b.failing[id] {
		b.mu.Unlock()
		return geoenrich.Item{}, &missingErr{id}
	}
	b.inflight++
	if b.inflight > b.maxInflight {
		b.maxInflight = b.inflight
	}
	if b.barrier > 0 && b.inflight >= b.barrier {
		b.once.Do(func() { close(b.tripped) })
	}
	waiting := b.barrier > 0 && !b.open
	b.mu.Unlock()
	defer func() {
		b.mu.Lock()
		b.inflight--
		b.mu.Unlock()
	}()
	if waiting {
		select {
		case <-b.tripped:
		case <-ctx.Done():
			return geoenrich.Item{}, ctx.Err()
		case <-time.After(3 * time.Second):
			b.mu.Lock()
			b.open = true
			b.mu.Unlock()
		}
	}
	if err := ctx.Err(); err != nil {
		return geoenrich.Item{}, err
	}
	item, ok := b.items[id]
	if !ok {
		return geoenrich.Item{}, &missingErr{id}
	}
	return item, nil
}

func makeItems(n int) map[string]geoenrich.Item {
	items := map[string]geoenrich.Item{}
	for i := 0; i < n; i++ {
		id := fmt.Sprintf("id%d", i)
		items[id] = geoenrich.Item{ID: id, Value: i * 7}
	}
	return items
}

