package geoenrich

import (
	"context"
	"sync"
)

// LookupPlaces loads the items for ids.
func LookupPlaces(ctx context.Context, b Backend, ids []string) ([]Item, error) {
	out := make([]Item, len(ids))
	errs := make([]error, len(ids))
	jobs := make(chan int)
	var wg sync.WaitGroup
	for w := 0; w < 4 && w < len(ids); w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range jobs {
				out[i], errs[i] = b.Get(ctx, ids[i])
			}
		}()
	}
	for i := range ids {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
	for _, err := range errs {
		if err != nil {
			return nil, err
		}
	}
	return out, nil
}

