package geoenrich_test

import (
	"context"
	"errors"
	"testing"

	"example.com/geoenrichmod/geoenrich"
)

type plainBackend map[string]geoenrich.Item

func (p plainBackend) Get(ctx context.Context, id string) (geoenrich.Item, error) {
	if it, ok := p[id]; ok {
		return it, nil
	}
	return geoenrich.Item{}, errors.New("no such item: " + id)
}

func TestBasicLoadsInOrder(t *testing.T) {
	b := plainBackend{"a": {ID: "a", Value: 1}, "b": {ID: "b", Value: 2}, "c": {ID: "c", Value: 3}}
	got, err := geoenrich.LookupPlaces(context.Background(), b, []string{"c", "a", "b", "a"})
	if err != nil {
		t.Fatal(err)
	}
	want := []string{"c", "a", "b", "a"}
	if len(got) != len(want) {
		t.Fatalf("got %v", got)
	}
	for i, id := range want {
		if got[i].ID != id {
			t.Fatalf("item %d = %v, want %s", i, got[i], id)
		}
	}
}

func TestBasicReportsAnUnknownId(t *testing.T) {
	b := plainBackend{"a": {ID: "a", Value: 1}}
	got, err := geoenrich.LookupPlaces(context.Background(), b, []string{"a", "zzz"})
	if err == nil || got != nil {
		t.Fatalf("got %v, %v; want a nil slice and an error", got, err)
	}
}

