package geoenrich

import "context"

// Item is a record held by the remote service.
type Item struct {
	ID    string
	Value int
}

// Backend is the remote service. Get is a network call: it can take a while, and it honours ctx.
type Backend interface {
	Get(ctx context.Context, id string) (Item, error)
}
